import {heading,cta} from './shared.js';
export const journey=()=>`<section class="problem-section"><div class="container">${heading('SUA EMPRESA PODE IR ALÉM','Seu negócio ainda depende<br>somente do Instagram ou WhatsApp?','Quando alguém pesquisa sua empresa ou o serviço que você oferece, o que ela encontra?')}<div class="problem-grid">${['Não possui um site profissional?','Sua empresa quase não aparece no Google?','Você perde oportunidades por falta de presença digital?'].map((x,i)=>`<div class="reveal"><span>0${i+1}</span><h3>${x}</h3></div>`).join('')}</div><p class="problem-end">É exatamente aí que <em>nós entramos.</em></p></div></section><section class="section container flow-section">${heading('DA DESCOBERTA AO CONTATO','Coloque sua empresa<br>no digital do jeito certo.')}<div class="flow">${[['G','GOOGLE','Seu cliente encontra'],['▱','SEU SITE','Conhece seu negócio'],['↗','WHATSAPP','Começa uma conversa'],['♡','CLIENTE','Cria uma conexão']].map(([i,t,p])=>`<div class="flow-step reveal"><span class="flow-icon">${i}</span><h3>${t}</h3><p>${p}</p></div>`).join('<span class="flow-arrow" aria-hidden="true">→</span>')}</div><p class="flow-caption">O Google ajuda as pessoas a encontrarem você. O site apresenta seu negócio.<br>O WhatsApp transforma o interesse em contato.</p></section><section class="section container benefits">${heading('MAIS QUE UM ENDEREÇO NA INTERNET','Por que ter um site profissional?')}<div class="benefit-grid">${[['◇','Mais credibilidade','Apresente seu negócio de maneira profissional.'],['◎','Presença digital','Tenha um endereço online para apresentar sua empresa.'],['⌖','Mais facilidade para ser encontrado','Ajude seus clientes a encontrarem suas informações e serviços.'],['↗','Contato rápido','Direcione visitantes diretamente para o seu WhatsApp.']].map(([i,t,p])=>`<article class="reveal"><span class="icon">${i}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="section container" id="processo">${heading('SIMPLES DO INÍCIO AO SITE','Seu projeto em três passos.')}<div class="process-grid">${[['01','A gente conversa','Você conta sobre seu negócio, seus objetivos e o que precisa comunicar.'],['02','Sua marca ganha forma','Organizamos o conteúdo e criamos um visual personalizado para sua página.'],['03','Você aprova. Seu site estreia.','Revisamos os detalhes juntos e preparamos a página para sua divulgação.']].map(([n,t,p])=>`<article class="reveal"><span class="step-number">${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>`;
